function PolicyPage({store,session,policy}){
  const {count}=useCart(),page=POLICIES[policy];
  if(!page)return <NotFound store={store}/>;
  return <div className="store policy-page" data-theme={currentMode()} style={themeVars(store.settings)}><Header settings={store.settings} session={session} cartCount={count}/>
    <main className="policy shell"><a className="back-link" href="/">&larr; BACK TO THE DROP</a>
      <span className="kicker">{page.kicker}</span><h1>{page.title}</h1>
      <p className="policy-updated">Last updated {page.updated}</p>
      {policySections(store.settings,policy,page).map(([heading,body],index)=><section key={heading||index}>{heading?<h2>{heading}</h2>:null}<p>{body}</p></section>)}
      <p className="policy-foot">Questions about anything on this page? Email <a href={`mailto:${SUPPORT_EMAIL}`}>{SUPPORT_EMAIL}</a>.</p>
    </main><Footer settings={store.settings}/></div>}


function Footer({settings}){return <footer className="site-footer"><div className="shell"><div>{settings.brand}<span>●</span></div><p>{settings.footerNote}</p><nav><a href="/#catalog">MERCH</a><a href="/account">ACCOUNT</a><a href="/contact">CONTACT</a></nav><nav className="footer-policies"><a href="/terms">TERMS</a><a href="/privacy">PRIVACY</a><a href="/shipping">SHIPPING</a></nav><small>© 2026 {settings.brand} · Student-run, not an official IIT Delhi store</small></div></footer>}
function Loading(){return <div className="loading"><span>THE IIT DELHI DROP</span><i>●</i></div>}
function NotFound({store}){return <div className="store" data-theme={currentMode()} style={themeVars(store.settings)}><Header settings={store.settings}/><div className="not-found"><span>404 / LOST ON CAMPUS</span><h1>This drop wandered off.</h1><a href="/">RETURN HOME <Icon name="arrow"/></a></div></div>}

function App(){const [store,setStore]=useState(null),[session,setSession]=useState(null);useEffect(()=>{api('/api/store').then(setStore);api('/api/account/session').then(setSession).catch(()=>{})},[]);if(!store)return <Loading/>;const path=location.pathname;if(path.startsWith('/studio'))return <Studio store={store}/>;if(POLICIES[path.replace('/','')])return <PolicyPage store={store} session={session} policy={path.replace('/','')}/>;if(path==='/login')return <LoginPage store={store} onSession={setSession}/>;if(path==='/account')return <AccountPage store={store} session={session}/>;if(path==='/cart')return <CartPage store={store} session={session}/>;if(path.startsWith('/products/'))return <ProductPage store={store} session={session} slug={decodeURIComponent(path.split('/').filter(Boolean).pop())}/>;return <Storefront store={store} session={session}/>}

createRoot(document.getElementById('root')).render(<App/>);
